const validItems = $input.all()
  .map(item => item.json)
  .filter(row =>
    String(row.ticker ?? '').trim() &&
    Number(row.quantity ?? 0) > 0 &&
    String(row.asset_type ?? '').trim()
  );

if (validItems.length < 2) {
  throw new Error('At least two valid portfolio holdings are required.');
}

const totalQuantity = validItems.reduce(
  (sum, row) => sum + Number(row.quantity),
  0
);

if (totalQuantity <= 0) {
  throw new Error('Portfolio quantity total must be greater than zero.');
}

const now = new Date();
const runId = `RUN-${now.toISOString().replace(/[-:TZ.]/g, '').slice(0, 14)}`;

return validItems.map(row => ({
  json: {
    run_id: runId,
    calculated_at: now.toISOString(),
    ticker: String(row.ticker).trim().toUpperCase(),
    quantity: Number(row.quantity),
    asset_type: String(row.asset_type).trim().toLowerCase(),
    portfolio_weight: Number((Number(row.quantity) / totalQuantity).toFixed(8)),
    historical_days: 90,
    data_provider: 'dummy-n8n-market-data'
  }
}));

const input = $input.first().json;
const assets = input.assets ?? {};
const tickers = Object.keys(assets).sort();

if (tickers.length < 2) {
  throw new Error('At least two assets are required for correlation analysis.');
}

const priceMaps = {};
for (const ticker of tickers) {
  priceMaps[ticker] = new Map(
    assets[ticker].prices.map(p => [p.date, Number(p.close)])
  );
}

const returnSeries = {};
for (const ticker of tickers) {
  const dates = [...priceMaps[ticker].keys()].sort();
  const values = [];

  for (let i = 1; i < dates.length; i++) {
    const previous = priceMaps[ticker].get(dates[i - 1]);
    const current = priceMaps[ticker].get(dates[i]);

    if (previous > 0 && current > 0) {
      values.push({
        date: dates[i],
        value: (current - previous) / previous
      });
    }
  }

  returnSeries[ticker] = new Map(values.map(v => [v.date, v.value]));
}

function pearson(a, b) {
  const n = a.length;
  if (n < 2) return 0;

  const meanA = a.reduce((s, v) => s + v, 0) / n;
  const meanB = b.reduce((s, v) => s + v, 0) / n;

  let numerator = 0;
  let denomA = 0;
  let denomB = 0;

  for (let i = 0; i < n; i++) {
    const da = a[i] - meanA;
    const db = b[i] - meanB;
    numerator += da * db;
    denomA += da * da;
    denomB += db * db;
  }

  const denominator = Math.sqrt(denomA * denomB);
  return denominator === 0 ? 0 : numerator / denominator;
}

const pairwise = [];
const matrix = {};

for (const ticker of tickers) {
  matrix[ticker] = {};
}

for (let i = 0; i < tickers.length; i++) {
  const a = tickers[i];
  matrix[a][a] = 1;

  for (let j = i + 1; j < tickers.length; j++) {
    const b = tickers[j];

    const commonDates = [...returnSeries[a].keys()]
      .filter(date => returnSeries[b].has(date))
      .sort();

    const valuesA = commonDates.map(date => returnSeries[a].get(date));
    const valuesB = commonDates.map(date => returnSeries[b].get(date));

    if (commonDates.length < 10) {
      throw new Error(`Insufficient overlapping return observations for ${a} and ${b}.`);
    }

    const correlation = pearson(valuesA, valuesB);

    pairwise.push({
      ticker_a: a,
      ticker_b: b,
      correlation: Number(correlation.toFixed(6)),
      absolute_correlation: Number(Math.abs(correlation).toFixed(6)),
      relationship:
        Math.abs(correlation) >= 0.7 ? 'High' :
        Math.abs(correlation) >= 0.4 ? 'Moderate' : 'Low'
    });

    matrix[a][b] = Number(correlation.toFixed(6));
    matrix[b][a] = Number(correlation.toFixed(6));
  }
}

return [{
  json: {
    run_id: input.run_id,
    calculated_at: input.calculated_at,
    historical_days: input.historical_days,
    data_provider: input.data_provider,
    tickers,
    matrix,
    pairwise
  }
}];

const input = $input.first().json;
const pairwise = input.pairwise ?? [];

if (pairwise.length === 0) {
  throw new Error('No pairwise correlations were calculated.');
}

const averageCorrelation =
  pairwise.reduce((sum, pair) => sum + pair.correlation, 0) / pairwise.length;

const diversificationScore = Math.max(
  0,
  Math.min(100, (1 - averageCorrelation) * 100)
);

const highest = [...pairwise].sort(
  (a, b) => b.correlation - a.correlation
)[0];

const lowest = [...pairwise].sort(
  (a, b) => a.correlation - b.correlation
)[0];

const riskLevel =
  diversificationScore >= 80 ? 'Excellent' :
  diversificationScore >= 60 ? 'Good' :
  diversificationScore >= 40 ? 'Moderate' :
  diversificationScore >= 20 ? 'Weak' :
  'Poor';

return [{
  json: {
    ...input,
    average_correlation: Number(averageCorrelation.toFixed(6)),
    diversification_score: Number(diversificationScore.toFixed(2)),
    risk_level: riskLevel,
    highest_correlated_pair: `${highest.ticker_a}/${highest.ticker_b}`,
    highest_pair_correlation: highest.correlation,
    lowest_correlated_pair: `${lowest.ticker_a}/${lowest.ticker_b}`,
    lowest_pair_correlation: lowest.correlation,
    holding_count: input.tickers.length,
    pair_count: pairwise.length
  }
}];

const input = $input.first().json;
const pairs = input.pairwise ?? [];

return pairs.map(pair => ({
  json: {
    run_id: input.run_id,
    calculated_at: input.calculated_at,
    ticker_a: pair.ticker_a,
    ticker_b: pair.ticker_b,
    correlation: pair.correlation,
    absolute_correlation: pair.absolute_correlation,
    relationship: pair.relationship
  }
}));

const items = $input.all();
const assets = {};

for (const item of items) {
  const data = item.json.body ?? item.json;
  const ticker = String(data.ticker ?? '').toUpperCase();

  if (!ticker || !Array.isArray(data.prices) || data.prices.length < 3) {
    continue;
  }

  assets[ticker] = {
    ticker,
    asset_type: data.asset_type ?? 'equity',
    prices: data.prices
      .map(p => ({
        date: String(p.date),
        close: Number(p.close)
      }))
      .filter(p => p.date && Number.isFinite(p.close) && p.close > 0)
      .sort((a, b) => a.date.localeCompare(b.date))
  };
}

const requestData = items[0]?.json ?? {};
const runId = requestData.run_id ?? `RUN-${Date.now()}`;

const tickers = Object.keys(assets);

if (tickers.length < 2) {
  throw new Error('At least two assets with valid historical prices are required.');
}

return [{
  json: {
    run_id: runId,
    calculated_at: requestData.calculated_at ?? new Date().toISOString(),
    historical_days: 90,
    data_provider: 'dummy-n8n-market-data',
    assets
  }
}];

const input = $input.first().json;
const pairwise = input.pairwise ?? [];

const labels = pairwise.map(
  pair => `${pair.ticker_a}/${pair.ticker_b}`
);

const values = pairwise.map(
  pair => Number(pair.correlation)
);

const chartConfig = {
  type: 'bar',
  data: {
    labels,
    datasets: [
      {
        label: 'Pairwise Correlation',
        data: values
      }
    ]
  },
  options: {
    title: {
      display: true,
      text: 'Portfolio Pairwise Correlation'
    },
    legend: {
      display: false
    },
    scales: {
      yAxes: [
        {
          ticks: {
            min: -1,
            max: 1
          },
          scaleLabel: {
            display: true,
            labelString: 'Correlation'
          }
        }
      ],
      xAxes: [
        {
          ticks: {
            autoSkip: false,
            maxRotation: 90,
            minRotation: 45
          }
        }
      ]
    }
  }
};

const encodedChart = encodeURIComponent(
  JSON.stringify(chartConfig)
);

const quickchartUrl =
  `https://quickchart.io/chart` +
  `?width=1000` +
  `&height=600` +
  `&format=png` +
  `&version=2` +
  `&c=${encodedChart}`;

return [
  {
    json: {
      ...input,
      quickchart_url: quickchartUrl
    }
  }
];

const input = $input.first().json;

const message = [
  'Portfolio Diversification Report',
  '',
  `Holdings: ${input.holding_count}`,
  `Average Correlation: ${input.average_correlation}`,
  `Diversification Score: ${input.diversification_score}/100`,
  `Risk Level: ${input.risk_level}`,
  '',
  `Highest correlation: ${input.highest_correlated_pair} ${input.highest_pair_correlation}`,
  `Lowest correlation: ${input.lowest_correlated_pair} ${input.lowest_pair_correlation}`,
  '',
  `Historical period: ${input.historical_days} days`
].join('\n');

return [{
  json: {
    ...input,
    slack_message: message
  }
}];

const input = $input.first().json;

return [{
  json: {
    run_id: input.run_id,
    calculated_at: input.calculated_at,
    holding_count: input.holding_count,
    average_correlation: input.average_correlation,
    diversification_score: input.diversification_score,
    risk_level: input.risk_level,
    highest_correlated_pair: input.highest_correlated_pair,
    highest_pair_correlation: input.highest_pair_correlation,
    lowest_correlated_pair: input.lowest_correlated_pair,
    lowest_pair_correlation: input.lowest_pair_correlation,
    historical_days: input.historical_days,
    data_provider: input.data_provider
  }
}];
